<?php
declare(strict_types=1);namespace App\Interface\Http\Discovery\Controller;use App\Application\Discovery\DTO\Request\CreateDiscoverySearchRequestDto;use App\Application\Discovery\Service\DiscoverWebResourcesService;use App\Application\Discovery\Service\ListDiscoveryResourcesService;use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Infrastructure\Http\ApiResponseFactory;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;final class DiscoveryController{public function __construct(private readonly AuthService $auth,private readonly DiscoverWebResourcesService $discover,private readonly ListDiscoveryResourcesService $list,private readonly ApiResponseFactory $responses){}public function list(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a,?string $type):ResponseInterface{return $this->run($r,$s,$a,fn()=> $this->list->list($type));}public function search(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a,CreateDiscoverySearchRequestDto $i):ResponseInterface{return $this->run($r,$s,$a,fn()=> $this->discover->discover($i));}private function run(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a,callable $action):ResponseInterface{try{$u=$this->auth->currentUser($a);if(!in_array('ADMIN',$u->roles,true))return $this->responses->problem($s,'FORBIDDEN','Permissao administrativa necessaria.',403,(string)$r->getAttribute('request_id'));return $this->responses->success($s,$action(),(string)$r->getAttribute('request_id'));}catch(\DomainException $e){return $this->responses->problem($s,'VALIDATION_FAILED',$e->getMessage(),422,(string)$r->getAttribute('request_id'));}}}
